const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const cp = require('node:child_process');
const sha = (v) => crypto.createHash('sha256').update(v).digest('hex');
const base = '/Users/dr3/dev-shit/Maestro/.maestro/playbooks/2026-10-30-Grok-Tier1';
const ledger = JSON.parse(fs.readFileSync('Plans/grok-tier1/parity.json', 'utf8'));
const receipt = JSON.parse(fs.readFileSync('Plans/grok-tier1/evidence/01-task-coverage.json', 'utf8'));
const state = JSON.parse(fs.readFileSync('Plans/grok-tier1/run-state.json', 'utf8'));
const baseline = JSON.parse(cp.execFileSync('git', ['show', `${receipt.sourceCommit}:Plans/grok-tier1/parity.json`], {encoding:'utf8', maxBuffer:8*1024*1024}));
const evidence = fs.readFileSync('Plans/grok-tier1/evidence/01.md', 'utf8');
const originalChecker = evidence.slice(evidence.indexOf('<summary>Exact audit checker source</summary>')).match(/```javascript\n([\s\S]*?)\n```/)[1];
// Reuse the recorded canonical AST/source/column checks. Only the review revision changes.
assert(originalChecker.includes('ledger.sourceCommit\n'));
new Function('require', originalChecker.replace('ledger.sourceCommit\n', 'ledger.taskCoverageReview.sourceCommit\n'))(require);
const docs = Object.fromEntries(fs.readdirSync(base).filter(f => /^GROK-TIER1-\d\d\.md$/.test(f)).map(f => [f, fs.readFileSync(path.join(base,f),'utf8')]));
const tasks = {};
const order = [];
for (const [file, text] of Object.entries(docs).sort()) {
    for (const [i, line] of text.split('\n').entries()) {
        const m = line.match(/^- \[([ x])\] (GT1-\d\d-\d\d[A-Z]?) (\w+): /);
        if (!m) continue;
        assert(!tasks[m[2]], `duplicate ${m[2]}`);
        tasks[m[2]] = {file, line:i+1, text:line, kind:m[3], checked:m[1]==='x'};
        order.push(m[2]);
    }
    assert(!/^\s*<!--\s*(?:maestro:halt|MAESTRO:HITL)/mi.test(text), file);
}
function validate(candidate, docTasks = tasks) {
    const rows = new Map(candidate.rows.map(r => [r.id,r]));
    assert.equal(rows.size, 134);
    assert.equal(candidate.rows.length, rows.size);
    for (const prior of baseline.rows) {
        const row = rows.get(prior.id);
        assert(row, prior.id);
        for (const field of ['id','outcome','required','kind','comparators','sourcePaths','versions','limitations','implementation','static','deterministic','live','evidenceApplicability'])
            assert.deepEqual(row[field], prior[field], `${prior.id}:${field}`);
        const expectedPlatforms = [...prior.platforms];
        if (expectedPlatforms.includes('win32-x64')) expectedPlatforms.push('win32-arm64');
        assert.deepEqual(row.platforms, expectedPlatforms, `${row.id}:platforms`);
        for (const blocker of prior.blockers.filter(b => b.code !== 'owner-task-scope-pending'))
            assert(row.blockers.some(b => JSON.stringify(b) === JSON.stringify(blocker)), `${row.id}:${blocker.id}`);
        assert(!row.blockers.some(b => b.code === 'owner-task-scope-pending'), row.id);
        assert(!row.ownerTasks.implementation.includes('GT1-01-07'), row.id);
        for (const role of ['implementation','test','verification','finalAcceptance']) assert(row.ownerTasks[role].length, `${row.id}:${role}`);
        for (const [role, owners] of Object.entries(row.ownerTasks)) {
            assert.equal(new Set(owners).size, owners.length, `${row.id}:${role}`);
            for (const id of owners) {
                assert(docTasks[id], `${row.id}:missing task ${id}`);
                if (role === 'test') assert.equal(docTasks[id].kind, 'TEST');
                if (['verification','live','finalAcceptance'].includes(role)) assert(['VERIFY','AUDIT','REVIEW'].includes(docTasks[id].kind));
            }
        }
        if (row.evidenceApplicability.live.applicable) assert(row.ownerTasks.live.length, `${row.id}:live`);
        const final = ['P47','P48'].includes(row.id) ? 'GT1-12-10' : 'GT1-12-06';
        assert(row.ownerTasks.finalAcceptance.includes(final));
        for (const alias of row.routes) {
            const binding = candidate.canonicalRouteBindings[alias];
            assert(binding, `${row.id}:${alias}`);
            if (alias !== 'offline-audit') {
                assert.deepEqual([binding.transport,binding.target], state.testEnvironment.matrix.parityRouteMapping[alias]);
                assert.equal(binding.qualification, 'not-run');
            }
        }
    }
    assert.equal(candidate.platformProfiles['win32-arm64']?.requiredCandidate, true);
    assert.equal(candidate.platformProfiles['win32-arm64']?.qualification, 'not-run');
    for (const packet of receipt.addedTasks) {
        assert(docTasks[packet.id], packet.id);
        assert.equal(docTasks[packet.id].text, packet.taskLine);
        assert.equal(docTasks[packet.id].checked, false);
        assert(order.indexOf(packet.id) < order.indexOf(packet.before), packet.id);
        assert(packet.rows.length, packet.id);
        const role = {IMPLEMENT:'implementation', TEST:'test', VERIFY:'verification'}[packet.kind];
        for (const id of packet.rows) assert(rows.get(id).ownerTasks[role].includes(packet.id), `${packet.id}:${id}`);
    }
    for (const id of Object.keys(docTasks).filter(id => !id.startsWith('GT1-01-')))
        assert(candidate.rows.some(row => Object.values(row.ownerTasks).some(owners => owners.includes(id))), `uncovered task ${id}`);
}
validate(ledger);
let mutations = 0;
const reject = (change) => { const copy = structuredClone(ledger); change(copy); assert.throws(() => validate(copy)); mutations++; };
reject(l => l.rows.pop());
reject(l => l.rows[0].required = false);
reject(l => l.rows.find(r=>r.id==='P08').kind = 'delivery');
reject(l => l.rows.find(r=>r.id==='S21').ownerTasks.implementation = []);
reject(l => l.rows.find(r=>r.id==='S16').ownerTasks.implementation = ['GT1-01-07']);
reject(l => l.rows.find(r=>r.id==='S34').ownerTasks.test = ['GT1-99-99']);
reject(l => l.rows.find(r=>r.id==='P18').ownerTasks.live = []);
reject(l => l.rows.find(r=>r.id==='P03').evidenceApplicability.live.applicable = false);
reject(l => l.rows.find(r=>r.id==='P39').platforms = ['darwin-arm64']);
reject(l => delete l.platformProfiles['win32-arm64']);
reject(l => l.canonicalRouteBindings['ssh-acp-candidate'].target = 'local');
reject(l => l.rows.find(r=>r.id==='P46').blockers = []);
reject(l => l.rows.find(r=>r.id==='S35').implementation = 'implemented');
reject(l => l.rows.find(r=>r.id==='P47').ownerTasks.finalAcceptance = ['GT1-12-06']);
let anchors = 0;
for (const finding of ledger.branchAudit.findings) for (const a of finding.anchors) {
    const file = ledger.sourceCatalog[a.sourceRef].path;
    assert.equal(sha(fs.readFileSync(file,'utf8').split(/\r?\n/)[a.line-1]), a.lineSha256, `${file}:${a.line}`);
    anchors++;
}
for (const [file, hashes] of Object.entries(receipt.documents)) assert.equal(sha(docs[file]), hashes.afterSha256, file);
for (const [id, entry] of Object.entries(receipt.taskCatalog)) {
    assert.equal(sha(tasks[id].text), entry.sha256, id);
    assert.equal(tasks[id].kind, entry.kind);
    assert.equal(tasks[id].line, entry.line, id);
    if (entry.originalTaskLineSha256) {
        const originalLine = id === 'GT1-01-07' ? tasks[id].text.replace('- [x]', '- [ ]') : tasks[id].text;
        assert.equal(sha(originalLine), entry.originalTaskLineSha256, `${id}:original task changed`);
    }
}
assert.deepEqual(state.live, ledger.liveBoundary);
assert.equal(state.live.enabled,false);
assert.equal(state.live.credentialsReference,null);
assert.equal(state.live.authorizationReference,null);
assert.equal(state.live.budgetUsd,0);
assert.equal(state.testEnvironment.runnerImplemented,false);
const changedSource = cp.execFileSync('git',['diff','--name-only',receipt.sourceCommit,'--','src','scripts','package.json','package-lock.json'],{encoding:'utf8'}).trim();
assert.equal(changedSource,'');
const result = {rows:134, referenceOutcomes:48, capabilities:29, sourceFiles:Object.keys(ledger.sourceCatalog).length,
    anchors, phase02to12Tasks:Object.keys(tasks).filter(id=>!id.startsWith('GT1-01-')).length,
    addedTasks:receipt.addedTasks.length, resolvedOwnerScopes:receipt.resolvedOwnerScopes.length,
    liveApplicableRows:ledger.rows.filter(r=>r.evidenceApplicability.live.applicable).length,
    platformExpandedRows:ledger.rows.filter(r=>r.platforms.includes('win32-arm64')).length,
    rejectedInvalidMutations:mutations, result:'pass', productAcceptance:'not-run', liveCalls:0};
fs.writeFileSync('tmp/grok-tier1-review/validation.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result));
